+    world: &flecs_ecs::prelude::World,
+    setup: Option<&str>,
+    stated: Option<[f64; 3]>,
+    rows: [(&str, &mut Option<RadialHeight>, RadialSource, f64); 4],
+) {
+    for (title, h, dsrc, doff) in rows {
+        radial_row(ui, world, setup, stated, title, h, dsrc, doff);
+    }
